@@ -1228,3 +1236,11 @@
-            if (errno == 0)
-                errno = ENOENT;
-            throwUnixException(env, errno);
+            if (res == EINTR) {
+                /* interrupted - repeat the call */
+                retry = 1;
+            } else if (res == ERANGE) {
+                /* insufficient buffer size so need larger buffer */
+                buflen += ENT_BUF_SIZE;
+                retry = 1;
+            } else {
+                /* lookup by uid: not found is treated as an error */
+                throwUnixException(env, res != 0 ? res : ENOENT);
+            }
